use std::fs

struct Job {
    name: string,
    prio: int,
}

fn best(jobs: Vec<Job>) -> int {
    let mut bi: int = -1
    let mut i: int = 0
    let n: int = jobs.len() as int
    while i < n {
        if bi < 0 || jobs[i as usize].prio > jobs[bi as usize].prio {
            bi = i
        }
        i += 1
    }
    bi
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut jobs: Vec<Job> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            println("error")
            continue
        }
        let cmd = parts[0]
        if cmd == "add" && parts.len() == 3 {
            match parts[2].parse::<int>() {
                Ok(p) => jobs.push(Job { name: parts[1], prio: p }),
                Err(_) => println("error"),
            }
        } else if cmd == "pop" && parts.len() == 1 {
            let b = best(jobs)
            if b < 0 {
                println("empty")
            } else {
                println(jobs[b as usize].name)
                jobs.remove(b as usize)
            }
        } else if cmd == "peek" && parts.len() == 1 {
            let b = best(jobs)
            if b < 0 {
                println("empty")
            } else {
                println(jobs[b as usize].name)
            }
        } else if cmd == "size" && parts.len() == 1 {
            println("${jobs.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while jobs.len() > 0 {
        let b = best(jobs)
        println("${jobs[b as usize].name} ${jobs[b as usize].prio}")
        jobs.remove(b as usize)
    }
}

